export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (min, max) => Math.random() * (max - min) + min;
export const randInt = (min, max) => Math.floor(rand(min, max + 1));
export const distance = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
export const formatNumber = (value) => Math.max(0, Math.round(value)).toLocaleString("en-US");
export const rectContains = (rect, x, y) => x >= rect.x && x <= rect.x + rect.w && y >= rect.y && y <= rect.y + rect.h;
export const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
export const easeOutBack = (t) => {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  const x = clamp(t, 0, 1) - 1;
  return 1 + c3 * Math.pow(x, 3) + c1 * Math.pow(x, 2);
};
export const pointInCircle = (cx, cy, radius, x, y) => distance(cx, cy, x, y) <= radius;

export function slotX(col) {
  return 57 + col * 60;
}

export function slotY(row) {
  return 248 + row * 58;
}

export function makeRoundedRectPath(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w * 0.5, h * 0.5);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

export function makeEllipsePath(ctx, cx, cy, rx, ry) {
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
  ctx.closePath();
}

export function drawGlossButton(ctx, x, y, w, h, r, colorTop, colorBottom, borderColor, shadowColor) {
  ctx.save();
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 3;
  ctx.shadowColor = shadowColor;
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, colorTop);
  grad.addColorStop(1, colorBottom);
  makeRoundedRectPath(ctx, x, y, w, h, r);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = borderColor;
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = "rgba(255,255,255,0.35)";
  ctx.beginPath();
  ctx.ellipse(x + w * 0.5, y + 16, 25, 10, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

export function drawStarPath(ctx, spikes, outerRadius, innerRadius) {
  const step = Math.PI / spikes;
  ctx.beginPath();
  for (let i = 0; i < spikes * 2; i += 1) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = -Math.PI * 0.5 + i * step;
    const px = Math.cos(angle) * radius;
    const py = Math.sin(angle) * radius;
    if (i === 0) {
      ctx.moveTo(px, py);
    } else {
      ctx.lineTo(px, py);
    }
  }
  ctx.closePath();
}

export function peakedProbability(n, start, peakStart, peakEnd, end, edgeProbability, peakProbability) {
  if (n < start || n > end) {
    return 0;
  }
  if (n < peakStart) {
    const t = (n - start) / Math.max(1, peakStart - start);
    return lerp(edgeProbability, peakProbability, t);
  }
  if (n <= peakEnd) {
    return peakProbability;
  }
  const t = (n - peakEnd) / Math.max(1, end - peakEnd);
  return lerp(peakProbability, edgeProbability, t);
}
